/**
 * Lift the volunteer portal's two quizzes into this repo's authoring content.
 *
 * The forty gate questions lived in two generated files in save7-os: the prompts
 * and option ids in `src-vol/03-quiz.js`, which ships to a browser, and the answers
 * in `supabase/functions/submit-quiz/key.ts`, which does not. That split was the
 * only thing making the gate a gate while the questions were a JavaScript literal.
 *
 * Now the bank is a table with an unreadable `is_correct` column, so the split is
 * enforced by the database instead and both halves can be authored in one place —
 * here, beside the course's own questions, where a content review can see them.
 *
 * Run: node scripts/import-gate-questions.mjs [path-to-save7-os]
 */
import { readFileSync, writeFileSync } from "node:fs";

const OS = process.argv[2] ?? new URL("../../save7-os", import.meta.url).pathname;
const OUT = new URL("../prisma/content/questions-gate.ts", import.meta.url).pathname;

/** Extract one brace-delimited literal after a marker, then evaluate it as data. */
function literalAfter(source, marker) {
  const start = source.indexOf(marker);
  if (start === -1) throw new Error(`marker not found: ${marker}`);
  // From the assignment, not from the marker: `KEY` carries a TypeScript type
  // annotation whose own braces come first and are not the literal.
  const open = source.indexOf("{", source.indexOf("=", start));
  let depth = 0;
  for (let i = open; i < source.length; i++) {
    if (source[i] === "{") depth++;
    else if (source[i] === "}" && --depth === 0) {
      // Data only — both files are generated literals with no calls in them.
      return new Function(`return ${source.slice(open, i + 1)}`)();
    }
  }
  throw new Error(`unbalanced braces after ${marker}`);
}

const quizzes = literalAfter(readFileSync(`${OS}/src-vol/03-quiz.js`, "utf8"), "const QUIZZES =");
const key = literalAfter(
  readFileSync(`${OS}/supabase/functions/submit-quiz/key.ts`, "utf8"),
  "export const KEY",
);

const ts = (s) => JSON.stringify(s);
const lines = [];
let count = 0;
const uncited = [];

for (const quiz of Object.values(quizzes)) {
  for (const q of quiz.questions) {
    const answer = key[q.id];
    if (!answer) throw new Error(`no key entry for ${q.id}`);
    if (!q.options.some((o) => o.id === answer.correct))
      throw new Error(`${q.id}: key names option ${answer.correct}, which is not on the question`);
    count++;

    lines.push(`  {`);
    lines.push(`    key: ${ts(q.id)},`);
    lines.push(`    scope: "GATE",`);
    lines.push(`    gate: ${ts(quiz.key)},`);
    lines.push(`    kind: "SINGLE",`);
    lines.push(`    topicTag: ${ts(`gate-${quiz.key}`)},`);
    lines.push(`    position: ${q.n},`);
    lines.push(`    prompt: ${ts(q.q)},`);
    lines.push(`    explanation: ${ts(answer.why)},`);
    lines.push(`    choices: [`);
    // Authored order, not the file's shuffled order: the option key is what a
    // submission names, so order here is presentation only and the app shuffles.
    for (const [i, o] of [...q.options].sort((a, b) => a.id.localeCompare(b.id)).entries()) {
      const correct = o.id === answer.correct ? ", isCorrect: true" : "";
      lines.push(`      { optionKey: ${ts(o.id)}, position: ${i}, text: ${ts(o.text)}${correct} },`);
    }
    lines.push(`    ],`);
    lines.push(`  },`);

    if (quiz.key === "clinical") uncited.push(q.id);
  }
}

const header = `import type { GateQuestionSeed } from "./types";

/**
 * The volunteer gate — the portal's two twenty-question quizzes, verbatim.
 *
 * GENERATED by scripts/import-gate-questions.mjs from save7-os. The prompts and
 * option ids come from \`src-vol/03-quiz.js\` and the answers from the
 * \`submit-quiz\` Edge Function's \`key.ts\`, so the two halves that were kept apart
 * to protect the key are reunited here and protected by RLS instead —
 * \`learn_choices.is_correct\` has no read path for any role.
 *
 * **Option keys are the portal's own** ('a'..'d'), unchanged, because
 * \`volunteer_quiz_attempts.answers\` already records historical submissions
 * against them. Renaming one would orphan every attempt ever taken.
 *
 * The pass mark stays the organisation's — 15 of 20 per quiz, per migration 0088,
 * and stored there rather than compiled in here.
 *
 * ⚠️ The twenty \`clinical\` items assert MELD thresholds, peak-VO2 figures, Milan
 * criteria and HPCSA registration rules that **no supplied source backs**. They are
 * registered in the content-review register uncleared, exactly as this repo's own
 * questions.ts refuses to test unverified clinical detail. Save7 signs them off or
 * they come out.
 */
export const gateQuestions: GateQuestionSeed[] = [
`;

writeFileSync(OUT, header + lines.join("\n") + "\n];\n");
console.log(`${count} gate questions written to prisma/content/questions-gate.ts`);
console.log(`${uncited.length} clinical items need citations: ${uncited.join(", ")}`);
